

from math import sqrt


from gmpy2 import *
from Crypto.Util.number import *

pqsqrt=isqrt(pq)

def find():
    i=0
    while True:
        x=pqsqrt+i
        x2n=x*x-pq
        xsqrt=isqrt(x2n)
        if xsqrt*xsqrt==x2n:
            return x,xsqrt
        else:
            continue
        
x,y=find()
        
        
